#!/usr/bin/env python3
"""Pinned Fumen chartless parse/writer/readback with original GA null-fallback configuration."""
import argparse,hashlib,json,subprocess,tempfile
from pathlib import Path
EDITOR='48e18f71655d0f0d86144c63239331833501fda2';FUMEN='0fe292f9c0ef70fb77d61cb54316a7e78dbf3c89'
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--editor-root',type=Path,required=True);p.add_argument('--fumen-root',type=Path,required=True);p.add_argument('--dotnet',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
blob=lambda root,pin,path:subprocess.check_output(['git','-C',str(root),'show',f'{pin}:{path}'])
paths=['Fumen/Converters/SMWriterBase.cs','Fumen/Converters/SMWriter.cs','Fumen/Converters/SSCWriter.cs','Fumen/Converters/SMReader.cs','Fumen/Converters/SSCReader.cs'];blobs={path:blob(a.fumen_root,FUMEN,path)for path in paths};editor=blob(a.editor_root,EDITOR,'StepManiaEditor/EditorSong.cs');assert subprocess.check_output(['git','-C',str(a.fumen_root),'rev-parse','HEAD'],text=True).strip()==FUMEN;subprocess.run(['git','-C',str(a.fumen_root),'diff','--exit-code',FUMEN,'--'],check=True,capture_output=True)
base='#TITLE:Chartless;#ARTIST:Artist;#GENRE:Private genre;#CREDIT:Private author;#BANNER:private.png;#MUSIC:music.ogg;#OFFSET:0.25;#BPMS:0=120;#STOPS:2=0.5;#DELAYS:3=0.125;#TIMESIGNATURES:0=3=4;#WARPS:4=1;#SCROLLS:0=1;#SPEEDS:0=1=0=0;#TICKCOUNTS:0=4;#FAKES:6=1;#COMBOS:0=1;#LABELS:0=Start;#ATTACKS:TIME=1:LEN=2:MODS=1.5x;#DISPLAYBPM:120;#LASTSECONDHINT:60;'
cases=[]
for source in ['sm','ssc']:
 for target in ['sm','ssc']:
  for anonymize in [False,True]:
   for omit in [False,True]:cases.append(dict(name=f'{source}_{target}_anon{int(anonymize)}_omit{int(omit)}',source=source,target=target,anonymize=anonymize,omit=omit,input=('#VERSION:0.83;'if source=='ssc'else'')+base))
program=r'''
using System;using System.IO;using Path=System.IO.Path;using System.Threading;using System.Threading.Tasks;using System.Linq;using System.Collections.Generic;using System.Text.Json;using System.Text.RegularExpressions;using Fumen;using Fumen.ChartDefinition;using Fumen.Converters;using static Fumen.Converters.SMWriterBase;
class Input{public string name{get;set;}="";public string source{get;set;}="";public string target{get;set;}="";public bool anonymize{get;set;}public bool omit{get;set;}public string input{get;set;}="";}
class Program{
 static async Task<Song> Read(string path,string format)=>format=="ssc"?await new SSCReader(path).LoadAsync(CancellationToken.None):await new SMReader(path).LoadAsync(CancellationToken.None);
 public static async Task Main(){var cases=JsonSerializer.Deserialize<List<Input>>(Console.In.ReadToEnd())!;var results=new List<object>();var root=Path.Combine(Path.GetTempPath(),"chartless-writer-"+Guid.NewGuid());Directory.CreateDirectory(root);try{foreach(var c in cases){var source=Path.Combine(root,c.name+".source."+c.source);var destination=Path.Combine(root,c.name+"."+c.target);File.WriteAllText(source,c.input);var song=await Read(source,c.source);var initialCharts=song.Charts.Count;if(initialCharts!=0)throw new Exception("source unexpectedly has charts");
 // Original EditorSong.Save sets SourceType to the output type and uses null
 // FallbackChart when there are no charts. Metadata-only adapters below mirror
 // its anonymize/removal fields, with no fake chart or timing event injection.
 song.SourceType=c.target=="ssc"?FileFormatType.SSC:FileFormatType.SM;song.Extras.RemoveSourceExtra("DISPLAYBPM");if(c.anonymize){song.Genre=null;song.SongSelectImage=null;foreach(var name in new[]{"CREDIT","ORIGIN","BACKGROUND","JACKET","CDIMAGE","DISCIMAGE","CDTITLE","LYRICSPATH","PREVIEWVID"})song.Extras.RemoveSourceExtra(name);}
 var custom=c.omit?null:new SMWriterCustomProperties();if(custom!=null){custom.CustomSongProperties["GASongDataVersion"]="1";custom.CustomSongProperties["GASongData"]="{\"SyncOffset\":0.25,\"FutureOwner\":57}";}
 var config=new SMWriterBaseConfig{FilePath=destination,Song=song,FallbackChart=null,PropertyEmissionBehavior=PropertyEmissionBehavior.Stepmania,MeasureSpacingBehavior=MeasureSpacingBehavior.UseLeastCommonMultiple,CustomProperties=custom,ForceOnlySongLevelTiming=false,WriteAttacksFromFallbackChart=c.target=="sm",OmitEmptyDisplayBpm=true,UseOutfoxFormatForSmx=true};bool written=c.target=="ssc"?new SSCWriter(config).Save():new SMWriter(config).Save();if(!written)throw new Exception("writer refused chartless output");var output=File.ReadAllText(destination);var readback=await Read(destination,c.target);var tags=new Dictionary<string,string>();foreach(Match match in Regex.Matches(output,@"#([A-Z0-9]+):([^;]*);",RegexOptions.IgnoreCase)){tags[match.Groups[1].Value.ToUpperInvariant()]=match.Groups[2].Value.Trim();}results.Add(new{c.name,initial_charts=initialCharts,output_charts=readback.Charts.Count,title=readback.Title,genre=readback.Genre,tags,output});}}finally{Directory.Delete(root,true);}Console.Write(JsonSerializer.Serialize(results));}}
'''
a.output.mkdir(parents=True,exist_ok=True);request=a.output/'request.json';request.write_text(json.dumps(cases,indent=2)+'\n')
with tempfile.TemporaryDirectory(prefix='deadsync-chartless-oracle-')as folder:
 root=Path(folder);(root/'Program.cs').write_text(program);(root/'Oracle.csproj').write_text(f'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><Nullable>disable</Nullable></PropertyGroup><ItemGroup><ProjectReference Include="{a.fumen_root}/Fumen/Fumen.csproj" /></ItemGroup></Project>');subprocess.run([str(a.dotnet),'build',str(root/'Oracle.csproj'),'-c','Release','--nologo','-v','quiet'],check=True);assembly=root/'bin/Release/net10.0/Oracle.dll';result=subprocess.run([str(a.dotnet),str(assembly)],input=json.dumps(cases),capture_output=True,text=True,check=True);expected=a.output/'expected.json';expected.write_text(json.dumps(json.loads(result.stdout),indent=2)+'\n');assembly_hash=hashlib.sha256(assembly.read_bytes()).hexdigest()
sha=lambda value:hashlib.sha256(value).hexdigest();provenance=dict(editor_commit=EDITOR,fumen_commit=FUMEN,editor_source_sha256=sha(editor),writer_reader_sources={path:sha(value)for path,value in blobs.items()},program_sha256=sha(program.encode()),assembly_sha256=assembly_hash,sdk=subprocess.check_output([str(a.dotnet),'--version'],text=True).strip(),request_sha256=sha(request.read_bytes()),expected_sha256=sha(expected.read_bytes()),scope='Actual pinned Fumen SM/SSC readers and writers, zero-chart input and null fallback, original GA writer configuration; metadata-only adapters for anonymize and fixed custom-song payload. No complete EditorSong work queue, native history, recovery or storage publication claim.')
(a.output/'provenance.json').write_text(json.dumps(provenance,indent=2)+'\n');print(json.dumps(dict(cases=len(cases),output=str(a.output))))
